input.command:
cat > pelican.html <<'EOF'
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Pelican Riding a Bicycle — animated SVG</title>
<style>
  :root{--bg:#111726;--ink:#e9eef7;--muted:#93a4bd}
  *{box-sizing:border-box}
  body{margin:0;min-height:100vh;display:grid;place-items:center;padding:28px;
    background:radial-gradient(1100px 700px at 50% 18%,#1c2537,var(--bg));
    color:var(--ink);font:15px/1.55 ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
  .stage{width:min(940px,100%)}
  h1{margin:0 0 12px;font-size:1.15rem;font-weight:650}
  figure{margin:0}
  .frame{border-radius:16px;overflow:hidden;box-shadow:0 24px 60px rgba(0,0,0,.5)}
  svg{display:block;width:100%;height:auto}
  figcaption{margin:12px 0 0;color:var(--muted);font-size:.82rem}

  .spin{animation:spin 1.15s linear infinite;transform-box:fill-box;transform-origin:center}
  @keyframes spin{to{transform:rotate(360deg)}}
  .bob{animation:bob 1.15s ease-in-out infinite}
  @keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
  .dash{animation:dash 1.15s linear infinite}
  @keyframes dash{to{transform:translateX(-80px)}}
  .cloud{animation:cloud 24s linear infinite}
  @keyframes cloud{0%{transform:translateX(140px);opacity:0}12%{opacity:.9}84%{opacity:.9}100%{transform:translateX(-760px);opacity:0}}
  .cloud.b{animation-duration:31s;animation-delay:-12s}
  .cloud.c{animation-duration:19s;animation-delay:-6s}
  .zip{animation:zip 1.15s linear infinite}
  @keyframes zip{0%{transform:translateX(40px);opacity:0}25%{opacity:.75}100%{transform:translateX(-150px);opacity:0}}
  .blink{animation:blink 4.6s ease-in-out infinite;transform-box:fill-box;transform-origin:center top}
  @keyframes blink{0%,86%{transform:scaleY(0)}90%{transform:scaleY(1)}94%,100%{transform:scaleY(0)}}
  .pouch{animation:pouch 1.15s ease-in-out infinite;transform-box:fill-box;transform-origin:center top}
  @keyframes pouch{0%,100%{transform:scale(1,1)}50%{transform:scale(1.04,1.16)}}
  .shadow{animation:shadow 1.15s ease-in-out infinite;transform-box:fill-box;transform-origin:center}
  @keyframes shadow{0%,100%{transform:scaleX(1);opacity:.26}50%{transform:scaleX(.95);opacity:.2}}
  .rays{animation:spin 30s linear infinite;transform-box:fill-box;transform-origin:center}
  @media (prefers-reduced-motion:reduce){*{animation:none!important}}
</style>
</head>
<body>
<main class="stage">
  <h1>Pelican Riding a Bicycle</h1>
  <figure>
    <div class="frame">
      <svg viewBox="0 0 800 420" role="img" aria-label="A white pelican pedalling a red bicycle along a road">
        <defs>
          <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stop-color="#d7ecf8"/><stop offset=".6" stop-color="#f3f0e2"/><stop offset="1" stop-color="#e9e0cd"/>
          </linearGradient>
          <linearGradient id="road" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stop-color="#4b5568"/><stop offset="1" stop-color="#394251"/>
          </linearGradient>
          <linearGradient id="hill" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stop-color="#b6d4c6"/><stop offset="1" stop-color="#9dc2b1"/>
          </linearGradient>
          <linearGradient id="plumage" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stop-color="#fbfdff"/><stop offset="1" stop-color="#d5e0ea"/>
          </linearGradient>
          <linearGradient id="pouchG" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stop-color="#f2b45c"/><stop offset="1" stop-color="#e08a3c"/>
          </linearGradient>
        </defs>
EOF
wc -c pelican.html
